 "content": "def transform(grid):
    """Recolor full-length straight marker lines to 2."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marked = [[False] * w for _ in range(h)]
    for r, row in enumerate(grid):
        if row[0] != bg and all(v == row[0] for v in row):
            marked[r] = [True] * w
    for c in range(w):
        color = grid[0][c]
        if color != bg and all(grid[r][c] == color for r in range(h)):
            for r in range(h):
                marked[r][c] = True
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 2
    return out

